def argument_of_unparenthesized_call?(node)
  child = node

  while (parent = child.parent)
    return false unless parent.pair_type? || parent.hash_type? || parent.call_type?

    if parent.call_type?
      return false if parent.receiver.equal?(child)

      return !parent.parenthesized? && parent.arguments.include?(child)
    end

    child = parent
  end

  false
end

